class Counter {
  static int total = 0;
  int id;
  Counter() { total++; id = total; }
}
class Main {
  public static void main(String[] args) {
    Counter a = new Counter();
    Counter b = new Counter();
    System.out.println(a.id + "," + b.id + "," + Counter.total);
  }
}

